import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans3d_kernel(
    .param .u64 x_ptr_param,
    .param .u64 w_ptr_param,
    .param .u64 y_ptr_param,
    .param .u32 N_param,
    .param .u32 IC_param,
    .param .u32 OC_param,
    .param .u32 Di_param,
    .param .u32 Hi_param,
    .param .u32 Wi_param,
    .param .u32 Kd_param,
    .param .u32 Kh_param,
    .param .u32 Kw_param,
    .param .u32 Do_param,
    .param .u32 Ho_param,
    .param .u32 Wo_param
)
{
    .reg .pred p0, p1, p2, p3, p4, p5, p6, p7;

    .reg .b32 rN, rIC, rOC, rDi, rHi, rWi, rKd, rKh, rKw, rDo, rHo, rWo;
    .reg .b32 r_idx, r_tmp;
    .reg .b32 r_n, r_oc, r_do, r_ho, r_wo;
    .reg .b32 r_ic, r_kd, r_kh, r_kw;
    .reg .s32 r_di, r_hi, r_wi;

    .reg .b64 x_ptr, w_ptr, y_ptr;
    .reg .b64 N64, IC64, OC64, Di64, Hi64, Wi64, Kd64, Kh64, Kw64, Do64, Ho64, Wo64;
    .reg .b64 total64, t64a, t64b, idx64, addrx, addrw, addry, off64;

    .reg .f32 f_acc, f_x, f_w;

    // Load parameters
    ld.param.u64 x_ptr, [x_ptr_param];
    ld.param.u64 w_ptr, [w_ptr_param];
    ld.param.u64 y_ptr, [y_ptr_param];

    ld.param.u32 rN,  [N_param];
    ld.param.u32 rIC, [IC_param];
    ld.param.u32 rOC, [OC_param];
    ld.param.u32 rDi, [Di_param];
    ld.param.u32 rHi, [Hi_param];
    ld.param.u32 rWi, [Wi_param];
    ld.param.u32 rKd, [Kd_param];
    ld.param.u32 rKh, [Kh_param];
    ld.param.u32 rKw, [Kw_param];
    ld.param.u32 rDo, [Do_param];
    ld.param.u32 rHo, [Ho_param];
    ld.param.u32 rWo, [Wo_param];

    // Convert dims to 64-bit
    cvt.u64.u32 N64,  rN;
    cvt.u64.u32 IC64, rIC;
    cvt.u64.u32 OC64, rOC;
    cvt.u64.u32 Di64, rDi;
    cvt.u64.u32 Hi64, rHi;
    cvt.u64.u32 Wi64, rWi;
    cvt.u64.u32 Kd64, rKd;
    cvt.u64.u32 Kh64, rKh;
    cvt.u64.u32 Kw64, rKw;
    cvt.u64.u32 Do64, rDo;
    cvt.u64.u32 Ho64, rHo;
    cvt.u64.u32 Wo64, rWo;

    // Compute linear global thread index
    .reg .b32 r_tid, r_cta, r_ntid;
    mov.u32 r_tid,  %tid.x;
    mov.u32 r_cta,  %ctaid.x;
    mov.u32 r_ntid, %ntid.x;
    mad.lo.s32 r_idx, r_cta, r_ntid, r_tid; // r_idx = blockIdx.x * blockDim.x + threadIdx.x

    // total64 = N*OC*Do*Ho*Wo
    mul.lo.u64 total64, N64, OC64;
    mul.lo.u64 total64, total64, Do64;
    mul.lo.u64 total64, total64, Ho64;
    mul.lo.u64 total64, total64, Wo64;

    // Bounds check
    cvt.u64.u32 idx64, r_idx;
    setp.ge.u64 p0, idx64, total64;
    @p0 bra EXIT;

    // Decompose r_idx into (n, oc, do, ho, wo) with row-major order N,OC,Do,Ho,Wo
    // wo = r_idx % rWo; t = r_idx / rWo;
    rem.u32 r_wo, r_idx, rWo;
    div.u32 r_tmp, r_idx, rWo;

    // ho = t % rHo; t = t / rHo;
    rem.u32 r_ho, r_tmp, rHo;
    div.u32 r_tmp, r_tmp, rHo;

    // do = t % rDo; t = t / rDo;
    rem.u32 r_do, r_tmp, rDo;
    div.u32 r_tmp, r_tmp, rDo;

    // oc = t % rOC; t = t / rOC;
    rem.u32 r_oc, r_tmp, rOC;
    div.u32 r_n,  r_tmp, rOC;

    // Initialize accumulator
    mov.f32 f_acc, 0f00000000;

    // ic loop
    mov.u32 r_ic, 0;
L_LOOP_IC:
    setp.ge.u32 p1, r_ic, rIC;
    @p1 bra L_DONE_IC;

    // kd loop
    mov.u32 r_kd, 0;
L_LOOP_KD:
    setp.ge.u32 p2, r_kd, rKd;
    @p2 bra L_NEXT_IC;

    // di = do - kd; bounds check 0 <= di < Di
    sub.s32 r_di, r_do, r_kd;
    setp.lt.s32 p3, r_di, 0;
    @p3 bra L_NEXT_KD;
    setp.ge.s32 p4, r_di, rDi;
    @p4 bra L_NEXT_KD;

    // kh loop
    mov.u32 r_kh, 0;
L_LOOP_KH:
    setp.ge.u32 p5, r_kh, rKh;
    @p5 bra L_NEXT_KD;

    // hi = ho - kh; bounds check
    sub.s32 r_hi, r_ho, r_kh;
    setp.lt.s32 p6, r_hi, 0;
    @p6 bra L_NEXT_KH;
    setp.ge.s32 p7, r_hi, rHi;
    @p7 bra L_NEXT_KH;

    // kw loop
    mov.u32 r_kw, 0;
L_LOOP_KW:
    setp.ge.u32 p0, r_kw, rKw;
    @p0 bra L_NEXT_KH;

    // wi = wo - kw; bounds check
    sub.s32 r_wi, r_wo, r_kw;
    setp.lt.s32 p1, r_wi, 0;
    @p1 bra L_INC_KW;
    setp.ge.s32 p2, r_wi, rWi;
    @p2 bra L_INC_KW;

    // Compute x address: (((n*IC + ic)*Di + di)*Hi + hi)*Wi + wi
    {
        .reg .b64 t0, t1;
        cvt.u64.u32 t0, r_n;
        mul.lo.u64 t0, t0, IC64;
        cvt.u64.u32 t1, r_ic;
        add.u64    t0, t0, t1;

        mul.lo.u64 t0, t0, Di64;
        cvt.u64.u32 t1, r_di;
        add.u64    t0, t0, t1;

        mul.lo.u64 t0, t0, Hi64;
        cvt.u64.u32 t1, r_hi;
        add.u64    t0, t0, t1;

        mul.lo.u64 t0, t0, Wi64;
        cvt.u64.u32 t1, r_wi;
        add.u64    t0, t0, t1;

        shl.b64    off64, t0, 2;
        add.u64    addrx, x_ptr, off64;
    }

    // Compute w address: (((ic*OC + oc)*Kd + kd)*Kh + kh)*Kw + kw
    {
        .reg .b64 u0, u1;
        cvt.u64.u32 u0, r_ic;
        mul.lo.u64 u0, u0, OC64;
        cvt.u64.u32 u1, r_oc;
        add.u64    u0, u0, u1;

        mul.lo.u64 u0, u0, Kd64;
        cvt.u64.u32 u1, r_kd;
        add.u64    u0, u0, u1;

        mul.lo.u64 u0, u0, Kh64;
        cvt.u64.u32 u1, r_kh;
        add.u64    u0, u0, u1;

        mul.lo.u64 u0, u0, Kw64;
        cvt.u64.u32 u1, r_kw;
        add.u64    u0, u0, u1;

        shl.b64    off64, u0, 2;
        add.u64    addrw, w_ptr, off64;
    }

    // Load and accumulate
    ld.global.f32 f_x, [addrx];
    ld.global.f32 f_w, [addrw];
    fma.rn.f32   f_acc, f_x, f_w, f_acc;

L_INC_KW:
    add.u32 r_kw, r_kw, 1;
    bra L_LOOP_KW;

L_NEXT_KH:
    add.u32 r_kh, r_kh, 1;
    bra L_LOOP_KH;

L_NEXT_KD:
    add.u32 r_kd, r_kd, 1;
    bra L_LOOP_KD;

L_NEXT_IC:
    add.u32 r_ic, r_ic, 1;
    bra L_LOOP_IC;

L_DONE_IC:
    // Store output y at linear index r_idx
    cvt.u64.u32 addry, r_idx;
    shl.b64     addry, addry, 2;
    add.u64     addry, y_ptr, addry;
    st.global.f32 [addry], f_acc;

EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans3d_kernel")

