        super().__init__()
        if isinstance(kernel_size, int):
            kernel_size = (kernel_size, kernel_size, kernel_size)
        if isinstance(stride, int):
            stride = (stride, stride, stride)
        if isinstance(padding, int):
            padding = (padding, padding, padding)
        if isinstance(output_padding, int):
            output_padding = (output_padding, output_padding, output_padding)

        # Specialization: only support stride=(1,1,1), padding=(0,0,0), output_padding=(0,0,0), groups=1, bias=False
        if stride != (1, 1, 1) or padding != (0, 0, 0) or output_padding != (0, 0, 0) or groups != 1 or bias:
            raise NotImplementedError("This specialized PTX implementation supports only stride=(1,1,1), padding=(0,0,0), output_padding=(0,0,0), groups=1, bias=False.")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.output_padding = tuple(output_padding)
        self.groups = groups
        self.bias = None  # bias not supported per specialization

        # Weight shape for ConvTranspose3d: (in_channels, out_channels // groups, kD, kH, kW)
        kD, kH, kW = self.kernel_size
        weight = torch.empty(in_channels, out_channels // groups, kD, kH, kW)
        nn.init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor.")
        if x.dtype != torch.float32:
            raise NotImplementedError("Only float32 tensors are supported.")
        if x.dim() != 5:
            raise ValueError("Input must be 5D (N, C, D, H, W).")
        if x.size(1) != self.in_channels:
            raise ValueError("Input channel mismatch.")

        x = x.contiguous()
        w = self.weight
        if w.device != x.device:
            w = w.to(device=x.device, dtype=x.dtype, non_blocking=True)
        w = w.contiguous()

        N, Cin, Di, Hi, Wi = x.shape
        kD, kH, kW = self.kernel_size

        # Output dims for transpose conv with stride=1, padding=0, output_padding=0
        Do = (Di - 1) * self.stride[0] - 2 * self.padding[0] + kD + self.output_padding[0]
        Ho = (Hi - 1) * self.stride[1] - 2 * self.padding[1] + kH + self.output_padding[1]
        Wo = (Wi - 1) * self.stride[2] - 2 * self.padding[2] + kW + self.output_padding[2]

        y = torch.empty((N, self.out_channels, Do, Ho, Wo), device=x.device, dtype=x.dtype)

        total = N * self.out_channels * Do * Ho * Wo
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module = _get_ptx_module()
        module.launch(
            "convtrans3d_kernel",
            grid=(int(grid_x), 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, w, y,
                i32(N), i32(Cin), i32(self.out_channels),
                i32(Di), i32(Hi), i32(Wi),
                i32(kD), i32(kH), i32(kW),
                i32(Do), i32(Ho), i32(Wo),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

